import React from 'react';
import { Alert, Box, Button, TextField, Typography } from '@mui/material';
import { AppDialog } from '@/components/ui/AppDialog';
import { useBodyScrollLock } from '@/hooks/useBodyScrollLock';
import { buildUpiPaymentUri, getUpiVirtualPaymentAddress, isUpiUri } from '@/utils/upi';
import { UpiLogo } from '@/components/ui/SvgIcons';

interface UpiLinkDialogProps {
    open: boolean;
    /** Current donation link value, used to prefill the address when it already holds one. */
    initialValue?: string;
    onClose: () => void;
    onConfirm: (donationLink: string) => void;
}

/**
 * Builds the value stored in an event's donation link. The event card turns a bare UPI address into a
 * full `upi://pay` URI at render time, so storing the address alone is enough; the extra fields here
 * exist for organisers who want to pin a payee name or amount into the link itself.
 */
export const UpiLinkDialog: React.FC<UpiLinkDialogProps> = ({ open, initialValue, onClose, onConfirm }) => {
    const [address, setAddress] = React.useState('');
    const [payeeName, setPayeeName] = React.useState('');
    const [amount, setAmount] = React.useState('');
    const [note, setNote] = React.useState('');

    useBodyScrollLock(open);

    React.useEffect(() => {
        if (!open) return;
        setAddress(getUpiVirtualPaymentAddress(initialValue) ?? '');
        setPayeeName('');
        setAmount('');
        setNote('');
    }, [open, initialValue]);

    const trimmedAddress = address.trim();
    const vpa = getUpiVirtualPaymentAddress(trimmedAddress);
    const hasExtras = !!payeeName.trim() || !!amount.trim() || !!note.trim();

    // With no extra fields the bare address is stored, keeping the saved value readable and letting the
    // event card generate a fresh transaction reference on every tap.
    const preview = React.useMemo(() => {
        if (!vpa) return null;
        return hasExtras
            ? buildUpiPaymentUri(vpa, { payeeName, note, amount })
            : vpa;
    }, [vpa, hasExtras, payeeName, note, amount]);

    const amountError = !!amount.trim() && !/^\d+(\.\d{1,2})?$/.test(amount.trim());
    const addressError = !!trimmedAddress && !vpa;
    const canSubmit = !!preview && !amountError;

    return (
        <AppDialog
            open={open}
            onClose={onClose}
            maxWidth="sm"
            titleIcon={<UpiLogo height={20} role="img" aria-label="UPI" style={{ display: 'block', width: 'auto' }} />}
            title="Build a UPI payment link"
            subtitle="Generates the value to store in the donation link field"
            actions={
                <>
                    <Button onClick={onClose} color="inherit">Cancel</Button>
                    <Button
                        onClick={() => preview && onConfirm(preview)}
                        color="primary"
                        variant="contained"
                        disabled={!canSubmit}
                    >
                        Use this link
                    </Button>
                </>
            }
        >
            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, mt: 1 }}>
                <TextField
                    label="UPI ID"
                    value={address}
                    onChange={(e) => setAddress(e.target.value)}
                    placeholder="alumni@okhdfcbank"
                    size="small"
                    fullWidth
                    autoFocus
                    error={addressError}
                    helperText={addressError
                        ? 'Enter a UPI ID in the form name@bank.'
                        : 'The account that receives the donation.'}
                    slotProps={{ htmlInput: { autoCapitalize: 'off', autoCorrect: 'off', spellCheck: false } }}
                />

                <TextField
                    label="Payee name (optional)"
                    value={payeeName}
                    onChange={(e) => setPayeeName(e.target.value)}
                    placeholder="Alumni Association"
                    size="small"
                    fullWidth
                    helperText="Shown inside the payer's UPI app. Defaults to the UPI ID."
                />

                <TextField
                    label="Amount in ₹ (optional)"
                    value={amount}
                    onChange={(e) => setAmount(e.target.value)}
                    placeholder="500"
                    size="small"
                    fullWidth
                    error={amountError}
                    helperText={amountError
                        ? 'Use digits only, with at most two decimals.'
                        : 'Leave blank to let each donor choose the amount.'}
                    slotProps={{ htmlInput: { inputMode: 'decimal' } }}
                />

                <TextField
                    label="Note (optional)"
                    value={note}
                    onChange={(e) => setNote(e.target.value)}
                    placeholder="Annual meet donation"
                    size="small"
                    fullWidth
                    helperText="Letters and numbers only, trimmed to 50 characters."
                />

                {preview && (
                    <Box>
                        <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mb: 0.5 }}>
                            Value to be saved
                        </Typography>
                        <Typography
                            variant="body2"
                            sx={{
                                fontFamily: 'monospace',
                                fontSize: '0.8rem',
                                wordBreak: 'break-all',
                                backgroundColor: 'action.hover',
                                borderRadius: 1,
                                p: 1,
                            }}
                        >
                            {preview}
                        </Typography>
                        <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 0.5 }}>
                            {isUpiUri(preview)
                                ? 'Saved as a full UPI link because you pinned a name, amount or note.'
                                : 'Saved as a plain UPI ID; the event page turns it into a payment link automatically.'}
                        </Typography>
                    </Box>
                )}

                <Alert severity="info" sx={{ '& .MuiAlert-message': { fontSize: '0.8rem' } }}>
                    Google Pay, PhonePe and Paytm open these links directly. BHIM only accepts links signed by a
                    registered merchant, so its users are shown the UPI ID to copy instead.
                </Alert>
            </Box>
        </AppDialog>
    );
};

export default UpiLinkDialog;
